import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

// THE WORLD IN PICTURES — 24 November 2026 (make.fun news-image-20261124 v2).
// The entry image is embedded below as base64 (one line: the image itself)
// and written out verbatim. No network, no other input, deterministic.
const B64 = "";

const outDir = process.env.MAKEFUN_OUTPUT_DIR ?? "./output";
mkdirSync(outDir, { recursive: true });
writeFileSync(join(outDir, "entry.png"), Buffer.from(B64, "base64"));
